import React, { useRef, useEffect } from 'react';
import { Message } from '../types';
import { ChatMessage } from './ChatMessage';
import { ChatInput } from './ChatInput';

interface ChatContainerProps {
  messages: Message[];
  isLoading: boolean;
  onSend: (question: string, description: string) => void;
  onSimilarQuestionClick: (question: string) => void;
  onClearHistory: () => void;
  onExportHistory: () => void;
}

export const ChatContainer: React.FC<ChatContainerProps> = ({
  messages,
  isLoading,
  onSend,
  onSimilarQuestionClick,
  onClearHistory,
  onExportHistory
}) => {
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleClear = () => {
    if (window.confirm('确定要清空所有对话记录吗？')) {
      onClearHistory();
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        <div className="header-content">
          <h2>💬 心理港湾</h2>
          <p>我在这里倾听您的心声</p>
        </div>
        <div className="header-actions">
          <button className="action-btn" onClick={onExportHistory}>
            📥 导出记录
          </button>
          <button className="action-btn" onClick={handleClear}>
            🗑️ 清空记录
          </button>
        </div>
      </div>

      <div className="chat-messages">
        {messages.map((message) => (
          <ChatMessage
            key={message.id}
            message={message}
            knowledgeSources={message.knowledgeSources}
            onSimilarQuestionClick={onSimilarQuestionClick}
          />
        ))}

        {isLoading && (
          <div className="loading">
            <div className="spinner">
              <div className="spinner-ring"></div>
              <div className="spinner-ring delay-1"></div>
              <div className="spinner-ring delay-2"></div>
            </div>
            <p>正在倾听您的心声...</p>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      <ChatInput onSend={onSend} disabled={isLoading} />
    </div>
  );
};
